const headers = $json.headers || {};
const authHeader = headers.authorization || headers.Authorization || '';
const query = $json.query || {};
const entity = String(query.entity || 'overview').trim().toLowerCase();
const allowed = new Set(['overview','all','jobs','solutions','technologies','learnings','recommendations','relationships']);
if (!String(authHeader).toLowerCase().startsWith('bearer ')) return [{ json: { ok: false, statusCode: 401, errorCode: 'UNAUTHORIZED', message: 'Missing bearer token' } }];
if (!allowed.has(entity)) return [{ json: { ok: false, statusCode: 400, errorCode: 'INVALID_ENTITY', message: 'Unsupported Delivery Intelligence entity' } }];
return [{ json: { ok: true, token: String(authHeader).replace(/^Bearer\s+/i, ''), entity, projectId: query.projectId || query.project_id || null, limit: Math.min(Number(query.limit || 100), 300) } }];

const req = $('Prepare DI Catalog Request').first().json;
const auth = $('Verify Catalog Supabase Auth User').first().json || {};
const rawProfile = $('Fetch Catalog Q-Ops User Profile').first().json;
const profile = Array.isArray(rawProfile) ? rawProfile[0] : rawProfile;
if (!auth.id) return [{ json: { ok: false, statusCode: 401, errorCode: 'UNAUTHORIZED', message: 'Invalid Supabase Auth token' } }];
if (!profile?.id || profile.status !== 'active') return [{ json: { ok: false, statusCode: 403, errorCode: 'PROFILE_NOT_ACTIVE', message: 'Active Q-Ops user profile not found' } }];
const rows = name => $items(name).map(i => i.json).filter(r => r && Object.keys(r).length);
const memberships = rows('Fetch Catalog Project Memberships');
const memberIds = memberships.map(r => r.project_id).filter(Boolean);
const isAdmin = profile.role === 'admin';
const projectId = req.projectId || null;
const canProject = id => isAdmin || !id || memberIds.includes(id);
const visibilityOk = r => isAdmin || ['organization','ai_sanitized_only'].includes(r.visibility_level) || canProject(r.project_id || r.source_project_id);
const matchesProject = r => !projectId || [r.project_id, r.source_project_id, r.source_entity_id, r.target_entity_id].includes(projectId);
const projects = rows('Fetch DI Catalog Projects').filter(p => canProject(p.id));
const projectMap = Object.fromEntries(projects.map(p => [p.id, p]));
const rawJobs = rows('Fetch DI Catalog Jobs').filter(r => canProject(r.project_id) && matchesProject(r)).slice(0, req.limit);
const rawSolutions = rows('Fetch DI Catalog Solutions').filter(r => visibilityOk(r) && matchesProject(r)).slice(0, req.limit);
const rawTechnologies = rows('Fetch DI Catalog Technologies');
const rawProjectTech = rows('Fetch DI Catalog Project Technologies').filter(r => canProject(r.project_id) && (!projectId || r.project_id === projectId));
const rawSolutionTech = rows('Fetch DI Catalog Solution Technologies');
const rawAssets = rows('Fetch DI Catalog Solution Assets').filter(r => visibilityOk(r));
const rawLearnings = rows('Fetch DI Catalog Learnings').filter(r => visibilityOk(r) && matchesProject(r)).slice(0, req.limit);
const rawRelationships = rows('Fetch DI Catalog Relationships').filter(r => visibilityOk(r) && matchesProject(r)).slice(0, req.limit);
const rawRecommendations = rows('Fetch DI Catalog Recommendations').filter(r => canProject(r.project_id) && matchesProject(r)).slice(0, req.limit);
const techById = Object.fromEntries(rawTechnologies.map(t => [t.id, t]));
const solutionById = Object.fromEntries(rawSolutions.map(s => [s.id, s]));
const learningById = Object.fromEntries(rawLearnings.map(l => [l.id, l]));
const recommendationById = Object.fromEntries(rawRecommendations.map(r => [r.id, r]));
const solutionIds = new Set(rawSolutions.map(s => s.id));
const visibleTechIds = new Set(rawProjectTech.map(pt => pt.technology_id));
rawSolutionTech.filter(st => solutionIds.has(st.solution_id)).forEach(st => visibleTechIds.add(st.technology_id));
const technologies = rawTechnologies.filter(t => !projectId || visibleTechIds.has(t.id)).map(t => { const usage = rawProjectTech.filter(pt => pt.technology_id === t.id); const solutionLinks = rawSolutionTech.filter(st => st.technology_id === t.id && solutionById[st.solution_id]); return { type: 'technology', id: t.id, title: t.name, name: t.name, normalizedName: t.normalized_name, summary: t.description || t.category || 'Technology detected by Delivery Intelligence.', category: t.category, vendor: t.vendor, tags: t.tags || [], usageCount: usage.length, projects: usage.map(pt => ({ projectId: pt.project_id, projectName: projectMap[pt.project_id]?.name || pt.project_id, confidenceScore: pt.confidence_score, sourceType: pt.source_type, sourceRef: pt.source_ref })), relatedSolutions: solutionLinks.map(st => ({ solutionId: st.solution_id, title: solutionById[st.solution_id]?.title })), updatedAt: t.updated_at, raw: t }; }).slice(0, req.limit);
const assetsBySolution = rawAssets.reduce((acc, asset) => { (acc[asset.solution_id] ||= []).push(asset); return acc; }, {});
const techBySolution = rawSolutionTech.reduce((acc, link) => { if (techById[link.technology_id]) (acc[link.solution_id] ||= []).push({ id: link.technology_id, name: techById[link.technology_id].name, category: techById[link.technology_id].category }); return acc; }, {});
const solutions = rawSolutions.map(s => ({ type: 'solution', id: s.id, title: s.title, slug: s.slug, summary: s.summary || s.ai_summary || s.problem_statement, problemStatement: s.problem_statement, implementationApproach: s.implementation_approach, qaApproach: s.qa_approach, riskFactors: s.risk_factors || [], productionLearnings: s.production_learnings || [], implementationComplexity: s.implementation_complexity, applicabilityTags: s.applicability_tags || [], visibility: s.visibility_level, status: s.status, sourceProjectId: s.source_project_id, projectId: s.source_project_id, projectName: projectMap[s.source_project_id]?.name || s.source_project_id, technologies: techBySolution[s.id] || [], assets: assetsBySolution[s.id] || [], updatedAt: s.updated_at, raw: s }));
const learnings = rawLearnings.map(l => ({ type: 'learning', id: l.id, title: l.title, summary: l.learning_summary, category: l.category, impactLevel: l.impact_level, reusableRecommendation: l.reusable_recommendation, visibility: l.visibility_level, projectId: l.source_project_id, sourceProjectId: l.source_project_id, projectName: projectMap[l.source_project_id]?.name || l.source_project_id, sourceRef: l.source_ref, createdByAi: l.created_by_ai, createdAt: l.created_at, updatedAt: l.updated_at, raw: l }));
function resolveTitle(type, id) { if (!id) return null; if (type === 'project') return projectMap[id]?.name || id; if (type === 'technology') return techById[id]?.name || id; if (type === 'reusable_solution' || type === 'solution') return solutionById[id]?.title || id; if (type === 'learning') return learningById[id]?.title || id; if (type === 'recommendation') return recommendationById[id]?.title || id; return projectMap[id]?.name || techById[id]?.name || solutionById[id]?.title || learningById[id]?.title || recommendationById[id]?.title || id; }
const recommendations = rawRecommendations.map(r => ({ type: 'recommendation', id: r.id, title: r.title, summary: r.summary, rationale: r.rationale, recommendationType: r.recommendation_type, status: r.status, confidenceScore: r.confidence_score, projectId: r.project_id, projectName: projectMap[r.project_id]?.name || r.project_id, relatedEntityType: r.related_entity_type, relatedEntityId: r.related_entity_id, relatedTitle: resolveTitle(r.related_entity_type, r.related_entity_id), feedback: r.feedback || {}, createdAt: r.created_at, updatedAt: r.updated_at, raw: r }));
const relationships = rawRelationships.map(r => ({ type: 'relationship', id: r.id, title: `${r.source_entity_type} ${r.relationship_type} ${r.target_entity_type}`, summary: `${resolveTitle(r.source_entity_type, r.source_entity_id)} -> ${resolveTitle(r.target_entity_type, r.target_entity_id)}`, sourceEntityType: r.source_entity_type, sourceEntityId: r.source_entity_id, sourceTitle: resolveTitle(r.source_entity_type, r.source_entity_id), targetEntityType: r.target_entity_type, targetEntityId: r.target_entity_id, targetTitle: resolveTitle(r.target_entity_type, r.target_entity_id), relationshipType: r.relationship_type, confidenceScore: r.confidence_score, evidence: r.evidence || [], visibility: r.visibility_level, createdAt: r.created_at, raw: r }));
const jobs = rawJobs.map(j => ({ type: 'job', id: j.job_id, jobId: j.job_id, title: j.job_id, status: j.status, jobType: j.job_type, projectId: j.project_id, projectName: projectMap[j.project_id]?.name || j.project_id, input: j.input || {}, output: j.output || {}, error: j.error, createdAt: j.created_at, updatedAt: j.updated_at, counts: j.output?.persistResult?.counts || j.output?.extractionSummary || {} }));
const overview = { projects: projects.length, jobs: jobs.length, solutions: solutions.length, technologies: technologies.length, projectTechnologies: rawProjectTech.length, solutionTechnologies: rawSolutionTech.filter(st => solutionIds.has(st.solution_id)).length, solutionAssets: rawAssets.filter(a => solutionIds.has(a.solution_id)).length, learnings: learnings.length, relationships: relationships.length, recommendations: recommendations.length, latestJob: jobs[0] || null };
const payload = { overview, jobs, solutions, technologies, learnings, relationships, recommendations };
const entity = req.entity;
const items = entity === 'all' ? [...solutions, ...technologies, ...learnings, ...recommendations, ...relationships, ...jobs] : entity === 'overview' ? [] : payload[entity] || [];
return [{ json: { ok: true, entity, projectId, generatedAt: new Date().toISOString(), counts: overview, items, data: payload } }];
